package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"sync"
	"sync/atomic"
)

// SecureChannel implements an encrypted bidirectional communication channel
// using AES-256-GCM with monotonically increasing nonces to prevent replay attacks.
type SecureChannel struct {
	sendCipher cipher.AEAD
	recvCipher cipher.AEAD
	sendNonce  uint64
	recvNonce  uint64
	sendMu     sync.Mutex
	recvMu     sync.Mutex
	conn       net.Conn
	closed     int32
}

const (
	maxMessageSize = 64 * 1024
	nonceSize      = 12
	// maxNonceValue prevents nonce overflow - we stop before reaching
	// the maximum to ensure we never reuse a nonce value.
	// With 96-bit nonces, the lower 64 bits are our counter.
	maxNonceValue = ^uint64(0) - 1 // Leave room for safety margin
)

func NewSecureChannel(conn net.Conn, sendKey, recvKey []byte) (*SecureChannel, error) {
	if len(sendKey) != 32 || len(recvKey) != 32 {
		return nil, errors.New("keys must be 256 bits")
	}

	sendBlock, err := aes.NewCipher(sendKey)
	if err != nil {
		return nil, fmt.Errorf("send cipher: %w", err)
	}
	sendAEAD, err := cipher.NewGCM(sendBlock)
	if err != nil {
		return nil, fmt.Errorf("send GCM: %w", err)
	}

	recvBlock, err := aes.NewCipher(recvKey)
	if err != nil {
		return nil, fmt.Errorf("recv cipher: %w", err)
	}
	recvAEAD, err := cipher.NewGCM(recvBlock)
	if err != nil {
		return nil, fmt.Errorf("recv GCM: %w", err)
	}

	sc := &SecureChannel{
		sendCipher: sendAEAD,
		recvCipher: recvAEAD,
		conn:       conn,
	}

	return sc, nil
}

// buildNonce constructs a 12-byte nonce from the counter value.
// Format: [4 bytes random prefix][8 bytes counter]
// The random prefix is generated once at channel creation and provides
// additional uniqueness across sessions.
func (sc *SecureChannel) buildNonce(counter uint64) []byte {
	nonce := make([]byte, nonceSize)
	// Use counter in the lower 8 bytes for monotonic ordering
	binary.BigEndian.PutUint64(nonce[4:], counter)
	return nonce
}

// Send encrypts and sends a message over the channel.
// Thread-safe: multiple goroutines may call Send concurrently.
func (sc *SecureChannel) Send(plaintext []byte) error {
	if atomic.LoadInt32(&sc.closed) != 0 {
		return errors.New("channel closed")
	}
	if len(plaintext) > maxMessageSize {
		return fmt.Errorf("message too large: %d > %d", len(plaintext), maxMessageSize)
	}

	sc.sendMu.Lock()
	defer sc.sendMu.Unlock()

	// Check nonce exhaustion - critical for GCM security
	if sc.sendNonce >= maxNonceValue {
		atomic.StoreInt32(&sc.closed, 1)
		sc.conn.Close()
		return errors.New("nonce space exhausted, channel must be rekeyed")
	}

	currentNonce := sc.sendNonce
	sc.sendNonce++ // Increment AFTER use

	nonce := sc.buildNonce(currentNonce)
	ciphertext := sc.sendCipher.Seal(nil, nonce, plaintext, nil)

	// Frame: [4 bytes length][12 bytes nonce][ciphertext]
	frame := make([]byte, 4+nonceSize+len(ciphertext))
	binary.BigEndian.PutUint32(frame[0:4], uint32(nonceSize+len(ciphertext)))
	copy(frame[4:4+nonceSize], nonce)
	copy(frame[4+nonceSize:], ciphertext)

	_, err := sc.conn.Write(frame)
	return err
}

// Receive decrypts and returns the next message from the channel.
// Thread-safe: multiple goroutines may call Receive concurrently.
func (sc *SecureChannel) Receive() ([]byte, error) {
	if atomic.LoadInt32(&sc.closed) != 0 {
		return nil, errors.New("channel closed")
	}

	// Read frame length
	lenBuf := make([]byte, 4)
	if _, err := io.ReadFull(sc.conn, lenBuf); err != nil {
		return nil, fmt.Errorf("read length: %w", err)
	}

	frameLen := binary.BigEndian.Uint32(lenBuf)
	if frameLen < uint32(nonceSize) || frameLen > uint32(maxMessageSize+nonceSize+sc.recvCipher.Overhead()) {
		return nil, errors.New("invalid frame length")
	}

	// Read frame body
	frameBuf := make([]byte, frameLen)
	if _, err := io.ReadFull(sc.conn, frameBuf); err != nil {
		return nil, fmt.Errorf("read frame: %w", err)
	}

	recvNonce := frameBuf[:nonceSize]
	ciphertext := frameBuf[nonceSize:]

	sc.recvMu.Lock()
	defer sc.recvMu.Unlock()

	// Verify nonce is monotonically increasing to prevent replay
	receivedCounter := binary.BigEndian.Uint64(recvNonce[4:])
	if receivedCounter < sc.recvNonce {
		return nil, fmt.Errorf("nonce replay detected: got %d, expected >= %d", receivedCounter, sc.recvNonce)
	}

	// Decrypt
	plaintext, err := sc.recvCipher.Open(nil, recvNonce, ciphertext, nil)
	if err != nil {
		return nil, fmt.Errorf("decryption failed: %w", err)
	}

	sc.recvNonce = receivedCounter + 1
	return plaintext, nil
}

// Close gracefully shuts down the channel.
func (sc *SecureChannel) Close() error {
	if atomic.CompareAndSwapInt32(&sc.closed, 0, 1) {
		return sc.conn.Close()
	}
	return nil
}

