type Server struct {
	listener net.Listener
	psk      []byte // Pre-shared key for deriving session keys
	wg       sync.WaitGroup
	quit     chan struct{}
}

func NewServer(addr string, psk []byte) (*Server, error) {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return nil, err
	}
	return &Server{
		listener: ln,
		psk:      psk,
		quit:     make(chan struct{}),
	}, nil
}

func (s *Server) deriveKeys(sessionID []byte) (sendKey, recvKey []byte) {
	// In production, use HKDF. Simplified for demonstration.
	sendKey = make([]byte, 32)
	recvKey = make([]byte, 32)
	copy(sendKey, s.psk[:32])
	copy(recvKey, s.psk[:32])
	// XOR with session ID for uniqueness
	for i := 0; i < len(sessionID) && i < 32; i++ {
		sendKey[i] ^= sessionID[i]
		recvKey[i] ^= sessionID[i] ^ 0xFF
	}
	return
}

func (s *Server) handleConnection(conn net.Conn) {
	defer s.wg.Done()
	defer conn.Close()

	// Read session ID (first 16 bytes from client)
	sessionID := make([]byte, 16)
	if _, err := io.ReadFull(conn, sessionID); err != nil {
		return
	}

	sendKey, recvKey := s.deriveKeys(sessionID)
	// Note: server's send = client's recv and vice versa
	ch, err := NewSecureChannel(conn, sendKey, recvKey)
	if err != nil {
		return
	}
	defer ch.Close()

	for {
		select {
		case <-s.quit:
			return
		default:
		}

		msg, err := ch.Receive()
		if err != nil {
			return
		}

		// Echo back (application logic would go here)
		if err := ch.Send(msg); err != nil {
			return
		}
	}
}

func (s *Server) Serve() {
	for {
		conn, err := s.listener.Accept()
		if err != nil {
			select {
			case <-s.quit:
				return
			default:
				continue
			}
		}
		s.wg.Add(1)
		go s.handleConnection(conn)
	}
}

func (s *Server) Shutdown() {
	close(s.quit)
	s.listener.Close()
	s.wg.Wait()
}

func main() {
	psk := make([]byte, 32)
	if _, err := rand.Read(psk); err != nil {
		panic(err)
	}

	srv, err := NewServer(":8443", psk)
	if err != nil {
		panic(err)
	}

	fmt.Println("Secure channel server listening on :8443")
	srv.Serve()
}
